import React, { useEffect, useRef } from 'react';

const SpiderWeb = () => {
  const canvasRef = useRef(null);
  const nodesRef = useRef([]);
  const connectionsRef = useRef([]);
  const mouseRef = useRef({ x: -1000, y: -1000 });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    let animationFrameId;

    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      initWeb();
    };

    class WebNode {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.originalX = x;
        this.originalY = y;
        this.vx = 0;
        this.vy = 0;
      }

      update(mouseX, mouseY) {
        const dx = this.x - mouseX;
        const dy = this.y - mouseY;
        const distance = Math.sqrt(dx * dx + dy * dy);
        const breakDistance = 150;

        if (distance < breakDistance) {
          const force = (breakDistance - distance) / breakDistance;
          const angle = Math.atan2(dy, dx);
          this.vx += Math.cos(angle) * force * 2;
          this.vy += Math.sin(angle) * force * 2;
        }

        this.x += this.vx;
        this.y += this.vy;

        const returnForce = 0.05;
        this.vx += (this.originalX - this.x) * returnForce;
        this.vy += (this.originalY - this.y) * returnForce;

        this.vx *= 0.9;
        this.vy *= 0.9;
      }
    }

    class WebConnection {
      constructor(node1, node2) {
        this.node1 = node1;
        this.node2 = node2;
        this.maxDistance = this.getDistance();
      }

      getDistance() {
        const dx = this.node1.x - this.node2.x;
        const dy = this.node1.y - this.node2.y;
        return Math.sqrt(dx * dx + dy * dy);
      }

      draw() {
        const distance = this.getDistance();
        const stretchRatio = distance / this.maxDistance;

        if (stretchRatio < 1.5) {
          const opacity = Math.max(0, 1 - (stretchRatio - 1) * 2);
          ctx.beginPath();
          ctx.moveTo(this.node1.x, this.node1.y);
          ctx.lineTo(this.node2.x, this.node2.y);
          ctx.strokeStyle = `rgba(99, 102, 241, ${0.2 * opacity})`;
          ctx.lineWidth = 0.5;
          ctx.stroke();
        }
      }
    }

    const initWeb = () => {
      nodesRef.current = [];
      connectionsRef.current = [];

      const spacing = 150;
      const cols = Math.ceil(canvas.width / spacing) + 1;
      const rows = Math.ceil(canvas.height / spacing) + 1;

      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const x = col * spacing;
          const y = row * spacing;
          nodesRef.current.push(new WebNode(x, y));
        }
      }

      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const index = row * cols + col;

          if (col < cols - 1) {
            connectionsRef.current.push(
              new WebConnection(nodesRef.current[index], nodesRef.current[index + 1])
            );
          }

          if (row < rows - 1) {
            connectionsRef.current.push(
              new WebConnection(nodesRef.current[index], nodesRef.current[index + cols])
            );
          }
        }
      }
    };

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      nodesRef.current.forEach(node => {
        node.update(mouseRef.current.x, mouseRef.current.y);
      });

      connectionsRef.current.forEach(connection => {
        connection.draw();
      });

      animationFrameId = requestAnimationFrame(animate);
    };

    const handleMouseMove = (e) => {
      mouseRef.current.x = e.clientX;
      mouseRef.current.y = e.clientY + window.scrollY;
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    document.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      document.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        zIndex: 1,
        opacity: 0.6
      }}
    />
  );
};

export default SpiderWeb;
